import com.jpexs.decompiler.flash.*;import com.jpexs.decompiler.flash.tags.*;import java.io.*;import java.util.*;
class VerifyAddress{public static void main(String[]args)throws Exception{var old=new SWF(new FileInputStream(args[0]),false);var next=new SWF(new FileInputStream(args[1]),false);int count=0;for(int j=0;j<old.getTags().size();j++)if(old.getTags().get(j) instanceof DoABC2Tag){var a=((DoABC2Tag)old.getTags().get(j)).getABC();var b=((DoABC2Tag)next.getTags().get(j)).getABC();for(var m:a.bodies)if(!Arrays.equals(m.getCodeBytes(),b.findBody(m.method_info).getCodeBytes()))throw new Exception("Method changed");for(int i=1;i<a.constants.getStringCount();i++)if(!a.constants.getString(i).equals(b.constants.getString(i))){if(!a.constants.getString(i).equals("http://disneyclient-menu-c1628fe98d65.herokuapp.com/")||!b.constants.getString(i).equals("http://207.180.3.127:8080/"))throw new Exception("Unexpected string change");count++;}}if(count!=1)throw new Exception("Expected one origin replacement");System.out.println("PASS: only backend origin changed; all method bytecode unchanged");}}
